SELECT id, service, log_ts, level, latency_ms, payload_json, context, COALESCE(context['trace'], 'unknown') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs;
